command:
curl -sL https://download.savannah.gnu.org/releases/freetype/freetype-old/freetype-2.4.11.tar.gz -o /tmp/ft.tgz || curl -sL https://sourceforge.net/projects/freetype/files/freetype2/2.4.11/freetype-2.4.11.tar.gz/download -o /tmp/ft.tgz
mkdir -p /tmp/ft && tar xzf /tmp/ft.tgz -C /tmp/ft --strip-components=1 && ls /tmp/ft | head
grep -rhoE "FT_EXPORT(_DEF)?\( *[^)]*\) *\n? *[A-Za-z_][A-Za-z0-9_]*" /tmp/ft/include /tmp/ft/src 2>/dev/null | head -2
python3 - <<'EOF'
import re,pathlib,sys
sys.path.insert(0,'tools')
from nid_names import compute_nid, load_db
from pathlib import Path
names=set()
for p in list(Path('/tmp/ft/include').rglob('*.h'))+list(Path('/tmp/ft/src').rglob('*.c'))+list(Path('/tmp/ft/src').rglob('*.h')):
    t=p.read_text(errors='ignore')
    for m in re.finditer(r"FT_(?:EXPORT|BASE|BASE_DEF|EXPORT_DEF)\s*\([^)]*\)\s*([A-Za-z_]\w*)\s*\(",t): names.add(m.group(1))
    for m in re.finditer(r"\b(FT_\w+|ft_\w+|TT_\w+|FTC_\w+)\b",t): names.add(m.group(1))
print("candidate names",len(names))
bynid={compute_nid(n):n for n in names}
try:
    db=load_db(Path('/tmp/aerolib.csv'))
except Exception as e:
    print("db fail",e); db={}
t=Path('core/libs/prx/libSceFreeTypeOt/Export.cpp').read_text()
for nid,fn in re.findall(r'APS5_EXPORT\("([^"]+)",\s*(\w+)\)',t):
    print(nid, fn, "| ft:", bynid.get(nid,'-'), "| db:", db.get(nid,'-'))
EOF
